window.__votdWeek && window.__votdWeek({"week":"2029-03-19","reading":"Doctrine and Covenants 23–26","days":[{"d":"2029-03-19","ref":"D&C 23:2","b":"D&C","c":23,"v":2,"he":"הוֹדַע אֶת־קְרִיאָתְךָ לַכְּנֵסִיָּה וְגַם לִפְנֵי הָעוֹלָם וְיִפָּתַח לִבְּךָ לְהַשְׁמִיעַ אֱמֶת מֵעַתָּה וְעַד עוֹלָם אָמֵן׃","en":"Make known thy calling unto the church, and also before the world, and thy heart shall be opened to preach the truth from henceforth and forever. Amen."},{"d":"2029-03-20","ref":"D&C 23:6","b":"D&C","c":23,"v":6,"he":"הִנֵּה מוֹדִיעַ אֲנִי לְךָ יוֹסֵף נַיְט בַּדְּבָרִים הָאֵלֶּה כִּי עָלֶיךָ לָשֵׂאת אֶת־צְלַבְךָ אֲשֶׁר בּוֹ תִתְפַּלֵּל בְּקוֹל לִפְנֵי הָעוֹלָם וְגַם בַּסֵּתֶר וּבְמִשְׁפַּחְתְּךָ וּבֵין רֵעֶיךָ וּבְכׇל־מָקוֹם׃","en":"Behold, I manifest unto you, Joseph Knight, by these words, that you must take up your cross, in the which you must pray vocally before the world as well as in secret, and in your family, and among your friends, and in all places."},{"d":"2029-03-21","ref":"D&C 24:6","b":"D&C","c":24,"v":6,"he":"וְנִתָּן לְךָ בָּרֶגַע מָה תְּדַבֵּר וּמָה תִּכְתֹּב וְיִשְׁמְעוּ אוֹ אֶשְׁלַח עֲלֵיהֶם קְלָלָה תַּחַת בְּרָכָה׃","en":"And it shall be given thee in the very moment what thou shalt speak and write, and they shall hear it, or I will send unto them a cursing instead of a blessing."},{"d":"2029-03-22","ref":"D&C 24:15","b":"D&C","c":24,"v":15,"he":"וּבְכׇל־מָקוֹם אֲשֶׁר תָּבֹאוּ וְלֹא יְקַבְּלוּ אֶתְכֶם בִּשְׁמִי תַּעַזְבוּ קְלָלָה תַּחַת בְּרָכָה בִּנְעֹר אֶת־עֲפַר רַגְלֵיכֶם עֲלֵיהֶם לְעֵדוּת וְטַהֲרוּ רַגְלֵיכֶם בַּדֶּרֶךְ׃","en":"And in whatsoever place ye shall enter, and they receive you not in my name, ye shall leave a cursing instead of a blessing, by casting off the dust of your feet against them as a testimony, and cleansing your feet by the wayside."},{"d":"2029-03-23","ref":"D&C 25:4","b":"D&C","c":25,"v":4,"he":"אַל תִּתְאוֹנְנִי עַל אֲשֶׁר לֹא רָאִית כִּי נֶעֶלְמוּ מִמֵּךְ וּמִן הָעוֹלָם וְזֹאת חׇכְמָה בִּי לְעֵת תָּבוֹא׃","en":"Murmur not because of the things which thou hast not seen, for they are withheld from thee and from the world, which is wisdom in me in a time to come."},{"d":"2029-03-24","ref":"D&C 25:12","b":"D&C","c":25,"v":12,"he":"כִּי חָפְצָה נַפְשִׁי בְּשִׁיר הַלֵּב אָכֵן שִׁיר הַצַּדִּיקִים תְּפִלָּה הִיא לִי וְתֵעָנֶה בִּבְרָכָה עַל רֹאשָׁם׃","en":"For my soul delighteth in the song of the heart; yea, the song of the righteous is a prayer unto me, and it shall be answered with a blessing upon their heads."},{"d":"2029-03-25","ref":"D&C 26:2","b":"D&C","c":26,"v":2,"he":"וְכׇל־הַדְּבָרִים יֵעָשׂוּ עַל־פִּי הַכֹּל בַּכְּנֵסִיָּה בִּתְפִלָּה רַבָּה וּבֶאֱמוּנָה כִּי כׇל־הַדְּבָרִים תְּקַבְּלוּ בֶּאֱמוּנָה אָמֵן׃","en":"And all things shall be done by common consent in the church, by much prayer and faith, for all things you shall receive by faith. Amen."}]});
